// ================= 配置区域 =================

// 2. 【核心】四种颜色渐变配置
// 您可以任意修改这里的颜色和 offset 位置
// 逻辑：进度条会像一个窗口，从左到右滑过这个色带
const colorConfig = [
	{ offset: 0.0, color: '#57FE9F' }, // 0%  绿色
	{ offset: 0.4, color: '#00E8F3' }, // 40% 蓝色 (0-40% 绿变蓝)
	{ offset: 0.7, color: '#E8A43A' }, // 70% 黄色 (40-70% 蓝变黄)
	{ offset: 1.0, color: '#FF0E00' }  // 100% 红色 (70-100% 黄变红)
]
// 如果您想保持“前50%全是绿色”，只需把配置改成：
// [
//   { offset: 0.0, color: '#16CEB9' },
//   { offset: 0.5, color: '#16CEB9' }, // 强制 50% 处依然是绿
//   { offset: 0.75, color: '#FF9F40' },
//   { offset: 1.0, color: '#FF6384' }
// ]

// ================= 逻辑处理区域 (无需修改) =================

// 1. 颜色插值工具
function lerpColor(c1, c2, factor) {
	let rgb1 = echarts.color.parse(c1)
	let rgb2 = echarts.color.parse(c2)
	let r = Math.round(rgb1[0] + factor * (rgb2[0] - rgb1[0]))
	let g = Math.round(rgb1[1] + factor * (rgb2[1] - rgb1[1]))
	let b = Math.round(rgb1[2] + factor * (rgb2[2] - rgb1[2]))
	return `rgba(${r},${g},${b}, 1)`
}

// 2. 动态计算当前进度的渐变方案
function getGradientState(value, spectrum) {
	// 边界处理
	if (value <= 0) {
		let c = spectrum[0].color
		return { stops: [{ offset: 0, color: c }, { offset: 1, color: c }], endColor: c }
	}
	if (value >= 100) {
		return { stops: spectrum, endColor: spectrum[spectrum.length - 1].color }
	}

	const ratio = value / 100

	// 裁剪：取出当前比例之前的所有颜色节点
	let stops = spectrum.filter(s => s.offset < ratio).map(s => ({
		offset: s.offset / ratio, // 重新归一化 offset
		color: s.color
	}))

	// 计算当前末端的插值颜色
	let lower = spectrum[0]
	let upper = spectrum[spectrum.length - 1]

	for (let i = 0; i < spectrum.length - 1; i++) {
		if (ratio >= spectrum[i].offset && ratio <= spectrum[i + 1].offset) {
			lower = spectrum[i]
			upper = spectrum[i + 1]
			break
		}
	}

	const range = upper.offset - lower.offset
	const localFactor = range === 0 ? 0 : (ratio - lower.offset) / range
	const endColor = lerpColor(lower.color, upper.color, localFactor)

	// 封口：添加末端颜色
	stops.push({ offset: 1, color: endColor })

	return { stops, endColor }
}

function createBarChartOption(value) {
	const gradientState = getGradientState(value, colorConfig)
	const shadowColor = gradientState.endColor.replace(', 1)', ', 0.6)')

	return {
